import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void swish_kernel(const half* input, half* output, int64_t total_elements) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        half x = input[idx];
        // Compute sigmoid: 1 / (1 + exp(-x))
        // Using faster approximation for sigmoid
        half sigmoid_x = __hdiv(__float2half(1.0f), __hadd(__float2half(1.0f), __hexp(__hneg(x))));
        output[idx] = __hmul(x, sigmoid_x);
    }
}

void swish_forward(const half* input, half* output, int64_t total_elements) {
    const int block_size = 256;
    const int grid_size = (total_elements + block_size - 1) / block_size;

    swish_kernel<<<grid_size, block_size>>>(input, output, total_elements);
    cudaDeviceSynchronize();
}
"""

# Python wrapper
def compile_and_run():
    # Compile the CUDA extension
    module = load_inline(
        name="swish_ext",
        cpp_sources="",
        cuda_sources=cuda_source,
        functions=["swish_forward"],
        verbose=True
    )

    return module

